import { optionLabels } from "../data/demo-profile.js";

export const escapeHtml=value=>String(value??"").replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#039;",'"':"&quot;"}[char]));
export const label=value=>optionLabels[value]||escapeHtml(value||"");
export const formatDate=value=>new Intl.DateTimeFormat("en-PH",{year:"numeric",month:"long",day:"numeric"}).format(new Date(`${value}T00:00:00`));
export const badge=metric=>`<span class="badge ${metric.sourceCategory==="within"?"badge-neutral":"badge-attention"}">${escapeHtml(metric.sourceCategoryLabel)}</span>`;
export function pageHeader(eyebrow,title,description,action=""){return `<header class="page-header"><div class="page-header-copy"><p class="eyebrow">${escapeHtml(eyebrow)}</p><h1>${escapeHtml(title)}</h1><p>${escapeHtml(description)}</p></div>${action}</header>`;}
export function notice(text,type="info",title="Educational-use prototype"){return `<div class="notice ${type==="warning"?"notice-warning":type==="success"?"notice-success":""}" role="note"><span class="notice-icon" aria-hidden="true">${type==="warning"?"!":"i"}</span><div><strong>${escapeHtml(title)}</strong><p class="supporting">${escapeHtml(text)}</p></div></div>`;}
export function toast(message){const region=document.querySelector("#toast-region");if(!region)return;region.innerHTML=`<div class="toast">${escapeHtml(message)}</div>`;setTimeout(()=>{region.innerHTML=""},3200)}
export function modal({title,body,confirmText="Confirm",cancelText="Cancel",danger=false,onConfirm}){const root=document.querySelector("#modal-root");root.innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${escapeHtml(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">×</button></div><div>${body}</div><div class="cluster spacer-top"><button class="button ${danger?"button-danger":"button-primary"}" data-action="confirm-modal">${escapeHtml(confirmText)}</button><button class="button button-secondary" data-action="close-modal">${escapeHtml(cancelText)}</button></div></section></div>`;const close=()=>{root.innerHTML=""};root.querySelectorAll('[data-action="close-modal"]').forEach(el=>el.addEventListener("click",event=>{if(event.target===el)close()}));root.querySelector('[data-action="confirm-modal"]').addEventListener("click",()=>{close();onConfirm?.()});root.querySelector(".modal").addEventListener("click",event=>event.stopPropagation());root.querySelector('[data-action="close-modal"]').focus();}
